<div class="store-wrap blade-page"><div class="blade-admin-workspace"><x-admin.navigation /><div class="ro-dashboard min-w-0"><header class="ro-hero"><h1>{{ $product->name }}</h1><a class="ro-button" href="{{ route('admin.products.edit',$product) }}">Editar producto</a></header><section class="ro-panel"><dl><dt>SKU</dt><dd>{{ $product->sku }}</dd><dt>Estado</dt><dd>{{ $product->status }}</dd><dt>Marca</dt><dd>{{ $product->brand?->name ?? 'Sin marca' }}</dd><dt>Categoría</dt><dd>{{ $product->primaryCategory?->name ?? 'Sin categoría' }}</dd><dt>Descripción corta</dt><dd>{{ $product->short_description }}</dd><dt>Descripción larga</dt><dd class="whitespace-pre-line">{{ $product->long_description ?? $product->description }}</dd><dt>Precios publicados</dt><dd>@php($snapshot = $product->priceSnapshots()->whereHas('pricePublication', fn($q) => $q->where('is_active',true)->where('status','published'))->latest('price_publication_id')->first()){{ $snapshot ? $snapshot->price_mxn.' MXN / '.$snapshot->price_usd.' USD' : 'Sin precio publicado' }}</dd><dt>Stock disponible</dt><dd>{{ max(0,$product->inventoryBalances->sum('qty_on_hand')-$product->inventoryBalances->sum('qty_reserved')) }}</dd><dt>Vigencia</dt><dd>{{ $product->available_from?->format('d/m/Y') ?? 'Sin inicio' }} — {{ $product->available_until?->format('d/m/Y') ?? 'Sin límite' }}</dd></dl><img src="{{ sprintf('https://picsum.photos/seed/product-%d/640/640', $product->id) }}" alt="{{ $product->name }}" loading="lazy" width="240"><a href="{{ route('admin.products.index') }}">Volver al catálogo</a></section></div></div></div>